package com.campuseventhub;
import java.io.IOException;import java.sql.Connection;import java.sql.PreparedStatement;import javax.servlet.ServletException;import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;
@WebServlet("/cancelRegistration") public class CancelRegistrationServlet extends HttpServlet{protected void doGet(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{HttpSession s=r.getSession(false);if(s==null||s.getAttribute("student_id")==null){p.sendRedirect("login.jsp");return;}try(Connection c=DBConnection.getConnection()){PreparedStatement x=c.prepareStatement("UPDATE event_registrations SET status='Cancelled' WHERE registration_id=? AND student_id=? AND status IN ('Pending','Approved')");x.setInt(1,Integer.parseInt(r.getParameter("registration_id")));x.setInt(2,(Integer)s.getAttribute("student_id"));x.executeUpdate();p.sendRedirect("myEvents");}catch(Exception e){p.setContentType("text/html;charset=UTF-8");p.getWriter().println("<h2>Error: "+e.getMessage()+"</h2>");}}}
